function calcular(datos) {
  var dia = function (iso) { return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10); };
  var N = 7;
  var pedidos = (datos && datos.pedidos) || [];
  var conf = {};
  conf["confirmado"] = true;
  conf["enviado"] = true;
  conf["entregado"] = true;
  conf["novedad"] = true;
  var etiquetas = [];
  var conteo = {};
  for (var n = N - 1; n >= 0; n--) {
    var eti = dia(new Date(Date.parse(datos.hoy) - n * 86400000).toISOString());
    etiquetas.push(eti);
    conteo[eti] = 0;
  }
  for (var i = 0; i < pedidos.length; i++) {
    var p = pedidos[i];
    if (!p || !conf[p.estado] || !p.creado) continue;
    var d = dia(p.creado);
    if (conteo[d] !== undefined) conteo[d] += 1;
  }
  var serie = [];
  var total = 0;
  for (var j = 0; j < etiquetas.length; j++) {
    var v = conteo[etiquetas[j]] || 0;
    total += v;
    serie.push({ etiqueta: etiquetas[j], valor: v });
  }
  return {
    valor: total,
    unidad: "pedidos",
    serie: serie,
    nota: "Cuenta pedidos en confirmado, enviado, entregado y novedad de los últimos 7 días por fecha de creación (hora Bogotá)."
  };
}

